import numpy as np
N,G=2,3
e=np.array([[-1.,1.2,2.4],[-.7,1.7,2.1]])
u=np.array([[1,1,1],[1,np.exp(2j*np.pi/3),np.exp(4j*np.pi/3)],[1,np.exp(4j*np.pi/3),np.exp(2j*np.pi/3)]])/np.sqrt(3)
frames=np.stack([np.eye(3),u]).astype(complex)
p=np.exp(-1j*np.array([[0.,0.,0.],[0.,.7,1.1],[0.,-.7,-1.1]]))
v=np.empty((N,N,G,3,3),complex)
for i in range(N):
 for j in range(N):
  for g in range(G):v[i,j,g]=frames[j].conj().T@np.diag(p[g])@frames[i]
w=np.array([[[1.4,.1j,-.1j],[-.1j,.7,.03j],[.1j,-.03j,.7]]])
qi=np.zeros((N,N),int); head=False
qi[0,0]=8
def _exception_code(fn):
    try:
        fn()
        return 0
    except ValueError:
        return 1
    except Exception:
        return 2
assert np.allclose(_exception_code(lambda: exciton_hamiltonian(e,v,w,qi,head)), target)

